// SIMULATED DOM using captured public composer icons. No provider/model request.
document.documentElement.dataset.twosFixtureProvider='DeepSeek';
document.body.innerHTML='<main><div data-role="user">TEST ONLY question</div><div data-role="assistant" data-message-id="fixture-answer">TEST ONLY complete answer</div><section id="composer"><textarea></textarea><div role="button" class="ds-button--primary ds-button--circle" id="control"></div></section></main>';
const api=window.twosProviderDOM, control=document.getElementById('control');
let checks=0;
const check=(value,label)=>{if(!value)throw Error(label);checks++;};
const icon=path=>{control.innerHTML='<svg viewBox="0 0 16 16"><path></path></svg>';control.querySelector('path').setAttribute('d',path);};
icon(shapes.send);control.classList.add('ds-button--disabled');
check(api.observe().state==='idle'&&api.replyState(api.replies()[0]).complete,'idle disabled Send proves completion');
check(api.deepSeekControl('send',true)===null,'disabled Send cannot dispatch');
control.classList.remove('ds-button--disabled');
check(api.deepSeekControl('send',true)===control,'enabled Send resolves exactly');
icon(shapes.stop);
check(api.observe().state==='running'&&api.isStop(control),'observed unlabeled Stop is running');
check(!api.replyState(api.replies()[0]).complete,'existing body cannot complete during Stop');
check(api.deepSeekControl('send')===null,'Stop never becomes Send');
icon('M0 0 L16 16');
check(api.observe().state==='unknown'&&!api.replyState(api.replies()[0]).complete,'changed icon fails closed');
control.setAttribute('aria-label','Send message');
check(api.observe().state==='idle','public semantics survive changed icon');
control.setAttribute('aria-label','Stop generating');
check(api.observe().state==='running','semantic Stop');
control.removeAttribute('aria-label');icon(shapes.send);
const duplicate=control.cloneNode(true);control.after(duplicate);
check(api.observe().state==='unknown'&&api.deepSeekControl('send',true)===null,'duplicate controls ambiguous');
duplicate.remove();const decoy=control.cloneNode(true);decoy.setAttribute('aria-label','Stop');document.querySelector('[data-role=assistant]').append(decoy);
check(api.observe().state==='idle'&&!api.isStop(decoy),'quoted controls not native controls');
const another=document.createElement('textarea');document.getElementById('composer').append(another);
check(api.observe().reason==='AMBIGUOUS_COMPOSER'&&api.deepSeekControl('send')===null,'independent composers remain ambiguous');
another.remove();
document.querySelector('[data-role=assistant]').remove();
const message=document.createElement('div');message.className='ds-message';
message.innerHTML='<div class="ds-markdown">TEST ONLY partial answer. <p>已停止</p></div>';
document.getElementById('composer').before(message);
const reply=message.querySelector('.ds-markdown');
check(api.replyState(reply).complete,'quoted stopped text is ordinary answer content');
const status=document.createElement('span');status.textContent='已停止';message.append(status);
check(!api.replyState(reply).complete&&api.replyState(reply).reason==='REPLY_INTERRUPTED','provider stopped status blocks a partial DeepSeek answer');
status.remove();const resume=document.createElement('button');resume.className='ds-button';resume.textContent='Continue generating';message.after(resume);
check(!api.replyState(reply).complete,'provider continuation control is not final completion');
const next=document.createElement('div');next.className='ds-message';next.innerHTML='<div class="ds-markdown">TEST ONLY later complete answer</div>';resume.after(next);
check(api.replyState(next.firstElementChild).complete,'older interrupted reply cannot taint a later answer');
return checks;
